const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Hood Canal geometry (approximate area)
  const hoodCanal = ee.Geometry.Polygon([
    [[-122.95, 47.9], [-122.85, 47.9], [-122.85, 47.5], [-122.95, 47.5], [-122.95, 47.9]]
  ]);

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Load Sentinel-2 collections for both periods
  const col2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(hoodCanal)
    .filterDate('2021-08-20', '2021-09-01')
    .map(maskS2clouds);

  const col2022 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(hoodCanal)
    .filterDate('2022-08-20', '2022-09-01')
    .map(maskS2clouds);

  const size2021 = col2021.size().getInfo();
  const size2022 = col2022.size().getInfo();

  console.log(`2021 Images: ${size2021}`);
  console.log(`2022 Images: ${size2022}`);

  // Check if collections are empty
  if (size2021 === 0 || size2022 === 0) {
    console.log("Insufficient data for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Create median composites and extract blue band
  const img2021 = col2021.median().select('B2');
  const img2022 = col2022.median().select('B2');

  // 5. Calculate statistics with pixel count validation
  const stats2021 = img2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: hoodCanal,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2022 = img2022.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: hoodCanal,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2021 = stats2021.B2_mean;
  const count2021 = stats2021.B2_count;
  const mean2022 = stats2022.B2_mean;
  const count2022 = stats2022.B2_count;

  console.log(`2021 Blue Mean: ${mean2021}, Pixels: ${count2021}`);
  console.log(`2022 Blue Mean: ${mean2022}, Pixels: ${count2022}`);

  // Check for no valid pixels
  if (count2021 === 0 || count2022 === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (mean2021 === null || mean2022 === null || isNaN(mean2021) || isNaN(mean2022)) {
    console.log("Calculation returned invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Compare blue brightness (higher values = brighter blue)
  const percentIncrease = ((mean2022 - mean2021) / mean2021) * 100;
  console.log(`Percent Change: ${percentIncrease.toFixed(2)}%`);

  // Consider >10% increase as "noticeable larger bloom"
  if (mean2022 > mean2021 && percentIncrease > 10) {
    console.log("2022 shows noticeably brighter blue (larger bloom).");
    console.log("<answer>A</answer>");
  } else {
    console.log("No noticeable larger bloom in 2022.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
